    }

    [Theory]
    [InlineData(60, 60, 0)]
    [InlineData(100, 100, 0)]
    [InlineData(115, 110, 5)]
    [InlineData(155, 150, 5)]
    [InlineData(205, 200, 5)]
    public void Balance_exactly_covering_amount_and_fee_is_enough(int balance, int amount, int fee)
    {
